/**
 * Decision pack: the inspectable summary, the exports and the review request.
 *
 * The pack on screen and the two downloads all read one snapshot, so they
 * cannot disagree. The snapshot is taken when the export starts, which is what
 * makes it safe to keep editing while a PDF renders.
 *
 * The PDF is generated by a library loaded only at export time. If that fails
 * for any reason - a blocked import, a rendering error - the printable view is
 * always there, and it is the same content rather than a degraded version of it.
 */

import { useState } from "react";
import { Download, FileText, Printer, Save, Trash2 } from "lucide-react";
import { snapshotToCsv, csvFilename } from "@/lib/gcc-lab/csv";
import { PLANNING_ESTIMATE_NOTE } from "@/lib/gcc-lab/snapshot";
import { formatMoney } from "@/lib/gcc-lab/currency";
import { cityLabel } from "@/lib/gcc-lab/cities";
import { roleLabel, seniorityLabel } from "@/lib/gcc-lab/roles";
import { STORAGE_EXPLANATION, hasSavedCase } from "@/lib/gcc-lab/storage";
import { CATEGORY_LABELS } from "@/lib/gcc-lab/defaults";
import { trackEvent } from "@/lib/analytics";
import ReviewRequest from "./ReviewRequest";
import { ActionButton, Note, Panel, ScrollX, Stat, SubHeading } from "./primitives";
import type { LabCase, useLabResults } from "./useLabCase";
import type { CurrencyCode } from "@/lib/gcc-lab/types";

export interface DecisionPackAreaProps {
  lab: LabCase;
  results: ReturnType<typeof useLabResults>;
  toDisplay: (value: number) => number | null;
}

/** Triggers a client-side download. Nothing leaves the browser. */
function downloadBlob(contents: string, filename: string, type: string) {
  const blob = new Blob([contents], { type });
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = filename;
  document.body.appendChild(anchor);
  anchor.click();
  document.body.removeChild(anchor);
  // Revoked on the next tick so Safari has time to start the download.
  window.setTimeout(() => URL.revokeObjectURL(url), 1000);
}

export default function DecisionPackArea({ lab, results, toDisplay }: DecisionPackAreaProps) {
  const { snapshot, cost, economics, risks, plan } = results;
  const currency: CurrencyCode = lab.profile.displayCurrency;
  const [pdfError, setPdfError] = useState<string | null>(null);
  const [pdfBusy, setPdfBusy] = useState(false);
  const [storageMessage, setStorageMessage] = useState<string | null>(null);

  const money = (value: number | null | undefined): string => {
    if (value == null) return "Not available";
    const converted = toDisplay(value);
    return converted == null ? "Not available" : formatMoney(converted, currency);
  };

  const downloadCsv = () => {
    // The snapshot is already frozen; later edits cannot reach this file.
    downloadBlob(
      snapshotToCsv(snapshot, { currency, convert: toDisplay }),
      csvFilename(snapshot),
      "text/csv;charset=utf-8",
    );
    trackEvent("export_succeeded", { format: "csv" });
  };

  const downloadPdf = async () => {
    setPdfBusy(true);
    setPdfError(null);
    try {
      const { exportPdf } = await import("@/lib/gcc-lab/pdf");
      await exportPdf({
        snapshot,
        risks,
        policies: results.policies,
        plan,
        displayCurrency: currency,
        toDisplay,
      });
      trackEvent("export_succeeded", { format: "pdf" });
    } catch {
      setPdfError(
        "The PDF did not generate. Everything in it is on this page - use Print, and choose Save as PDF, or download the CSV.",
      );
    } finally {
      setPdfBusy(false);
    }
  };

  return (
    <div className="space-y-5">
      <Panel
        title="Your decision pack"
        description={`Case ${snapshot.caseId}, generated ${snapshot.computedAt.slice(0, 10)}. Every figure below traces back to an input, a benchmark or a stated assumption.`}
        actions={
          <div className="flex flex-wrap gap-2 no-print">
            <ActionButton variant="secondary" onClick={downloadPdf} disabled={pdfBusy}>
              <FileText aria-hidden className="w-4 h-4" /> {pdfBusy ? "Generating..." : "Download PDF"}
            </ActionButton>
            <ActionButton variant="ghost" onClick={downloadCsv}>
              <Download aria-hidden className="w-4 h-4" /> CSV
            </ActionButton>
            <ActionButton variant="ghost" onClick={() => window.print()}>
              <Printer aria-hidden className="w-4 h-4" /> Print
            </ActionButton>
          </div>
        }
      >
        <Note title={snapshot.reviewState === "practitioner-reviewed" ? "Practitioner reviewed" : "Planning estimate"}>
          {PLANNING_ESTIMATE_NOTE}
        </Note>

        {pdfError && (
          <div className="mt-3 no-print">
            <Note tone="caution" title="PDF export failed">
              {pdfError}
            </Note>
          </div>
        )}

        <div className="mt-5 grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-2.5">
          <Stat label="First-year cash" value={money(cost.firstYearCash)} basis="derived" />
          <Stat label="Steady-state monthly" value={money(cost.steadyStateMonthly)} basis="derived" />
          <Stat
            label="Payback"
            value={
              economics.paybackMonth != null
                ? `Month ${economics.paybackMonth}`
                : economics.paybackState === "no-initial-deficit"
                  ? "No initial deficit"
                  : null
            }
            unavailable={
              economics.paybackState === "no-baseline"
                ? "No baseline entered."
                : "Not recovered inside the horizon."
            }
            basis="derived"
          />
          <Stat label="Unresolved questions" value={String(snapshot.openQuestions.length)} basis="derived" />
        </div>

        {snapshot.openQuestions.length > 0 && (
          <div className="mt-5">
            <Note tone="caution" title="What this pack cannot answer">
              <ul className="list-disc pl-4 space-y-1">
                {snapshot.openQuestions.map((question) => (
                  <li key={question}>{question}</li>
                ))}
              </ul>
            </Note>
          </div>
        )}
      </Panel>

      <Panel title="What is in the pack">
        <div className="space-y-5">
          <section>
            <SubHeading>Objective and baseline</SubHeading>
            <p className="text-sm text-body">{economics.differenceLabel}</p>
          </section>

          <section>
            <SubHeading>Team and hiring waves</SubHeading>
            {lab.profile.team.length === 0 ? (
              <p className="text-sm text-body-muted">No team configured yet.</p>
            ) : (
              <ScrollX label="Team">
                <table className="w-full min-w-[480px] text-sm">
                  <thead>
                    <tr className="text-left border-b border-black/[0.08]">
                      <th scope="col" className="py-2 pr-3 text-2xs uppercase tracking-[0.14em] text-body-muted font-semibold">Role</th>
                      <th scope="col" className="py-2 pr-3 text-2xs uppercase tracking-[0.14em] text-body-muted font-semibold">Seniority</th>
                      <th scope="col" className="py-2 pr-3 text-2xs uppercase tracking-[0.14em] text-body-muted font-semibold text-right">FTE</th>
                      <th scope="col" className="py-2 pr-3 text-2xs uppercase tracking-[0.14em] text-body-muted font-semibold text-right">Starts</th>
                      <th scope="col" className="py-2 text-2xs uppercase tracking-[0.14em] text-body-muted font-semibold">Figure from</th>
                    </tr>
                  </thead>
                  <tbody>
                    {lab.profile.team.map((row) => (
                      <tr key={row.id} className="border-b border-black/[0.04]">
                        <th scope="row" className="py-2 pr-3 text-left font-medium text-heading">{roleLabel(row.roleKey)}</th>
                        <td className="py-2 pr-3 text-body">{seniorityLabel(row.seniority)}</td>
                        <td className="py-2 pr-3 text-right tabular-nums text-body">{row.fte}</td>
                        <td className="py-2 pr-3 text-right tabular-nums text-body">Month {row.startMonth}</td>
                        <td className="py-2 text-xs text-body-muted">{row.overrideAnnual != null ? "Your figure" : "Planning band"}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </ScrollX>
            )}
          </section>

          <section>
            <SubHeading>Cost detail</SubHeading>
            <ScrollX label="Cost lines in the pack">
              <table className="w-full min-w-[420px] text-sm">
                <tbody>
                  {cost.lineItems
                    .filter((item) => item.total > 0 || item.coveredByBundle)
                    .map((item) => (
                      <tr key={item.category} className="border-b border-black/[0.04]">
                        <th scope="row" className="py-2 pr-3 text-left font-medium text-heading">{CATEGORY_LABELS[item.category]}</th>
                        <td className="py-2 text-right tabular-nums text-body">
                          {item.coveredByBundle ? "In the bundled fee" : `${money(item.steadyStateMonthly)} a month`}
                        </td>
                      </tr>
                    ))}
                </tbody>
              </table>
            </ScrollX>
            {cost.exclusions.length > 0 && (
              <p className="text-xs text-body-muted mt-2">
                Excluded: {cost.exclusions.join("; ")}
              </p>
            )}
          </section>

          <section>
            <SubHeading>City</SubHeading>
            <p className="text-sm text-body">
              {cityLabel(lab.activeScenario.cityOverride ?? lab.profile.city)}
              {lab.profile.cityIsDefault && " - still the workspace's opening assumption rather than a decision you have made."}
            </p>
          </section>

          <section>
            <SubHeading>Risks</SubHeading>
            {risks.length === 0 ? (
              <p className="text-sm text-body-muted">No rules have fired.</p>
            ) : (
              <ol className="text-sm text-body space-y-1 list-decimal pl-4">
                {risks.slice(0, 6).map((risk) => (
                  <li key={risk.id}>
                    {risk.title} <span className="text-body-muted">- {risk.mitigation}</span>
                  </li>
                ))}
              </ol>
            )}
          </section>

          <section>
            <SubHeading>Launch tasks</SubHeading>
            <p className="text-sm text-body">{plan.note}</p>
          </section>

          <section>
            <SubHeading>Sources</SubHeading>
            <ul className="text-sm text-body space-y-1">
              {snapshot.sources.map((source) => (
                <li key={source.id}>
                  {source.title} - {source.publisher}, as of {source.asOf}
                  {source.url && (
                    <>
                      {" "}
                      <a href={source.url} target="_blank" rel="noopener noreferrer" className="text-accent-strong hover:underline">
                        link
                      </a>
                    </>
                  )}
                </li>
              ))}
            </ul>
          </section>

          <section>
            <SubHeading>Provenance</SubHeading>
            <dl className="text-xs text-body-muted grid grid-cols-2 sm:grid-cols-4 gap-2">
              <div><dt className="font-medium text-heading">Case</dt><dd>{snapshot.caseId}</dd></div>
              <div><dt className="font-medium text-heading">Model</dt><dd>{snapshot.modelVersion}</dd></div>
              <div><dt className="font-medium text-heading">Data</dt><dd>{snapshot.dataVersion}</dd></div>
              <div><dt className="font-medium text-heading">FX quoted</dt><dd>{snapshot.fxQuoteDate}</dd></div>
            </dl>
            <p className="text-xs text-body-muted mt-3">
              This pack is a planning aid. It is not tax, legal, employment or immigration advice, and nothing in it is a
              determination of eligibility for any scheme, treatment or arrangement.
            </p>
          </section>
        </div>
      </Panel>

      <div className="no-print">
      <Panel title="Keep this case">
        <p className="text-sm text-body leading-relaxed mb-3">{STORAGE_EXPLANATION}</p>
        {lab.storageState === "unavailable" && (
          <Note tone="caution" title="Storage is not available">
            This browser is not allowing site storage, so the case cannot be kept here. Download the CSV - it holds everything.
          </Note>
        )}
        <div className="flex flex-wrap items-center gap-2 mt-3">
          <ActionButton
            variant="ghost"
            disabled={lab.storageState === "unavailable"}
            onClick={() => {
              if (hasSavedCase() && !window.confirm("There is already a case saved on this device. Replace it?")) return;
              const result = lab.save();
              setStorageMessage(
                result.ok
                  ? `Saved on this device. It will be kept until ${result.expiresAt?.slice(0, 10)}.`
                  : (result.reason ?? "Could not save."),
              );
            }}
          >
            <Save aria-hidden className="w-4 h-4" /> Save on this device
          </ActionButton>
          <ActionButton
            variant="ghost"
            disabled={lab.storageState === "unavailable"}
            onClick={() => setStorageMessage(lab.restore() ?? "Loaded the case saved on this device.")}
          >
            Load saved case
          </ActionButton>
          <ActionButton
            variant="ghost"
            disabled={lab.storageState === "unavailable"}
            onClick={() => {
              lab.forget();
              setStorageMessage("Deleted from this device.");
            }}
          >
            <Trash2 aria-hidden className="w-4 h-4" /> Delete it
          </ActionButton>
        </div>
        {storageMessage && (
          <p aria-live="polite" className="text-xs text-body mt-3">
            {storageMessage}
          </p>
        )}
      </Panel>
      </div>

      <div className="no-print">
        <ReviewRequest
          snapshot={snapshot}
          displayCurrency={currency}
          toDisplay={toDisplay}
          onDownloadCsv={downloadCsv}
        />
      </div>
    </div>
  );
}
